create or replace TABLE KFL_PRODUCTION_CLONE_GCP_MIGRATION_20260608_0800.DBP_DATA.TS_MENGENAENDERUNGEN_WRITEBACK (
	MANDANT_ID NUMBER(38,0) NOT NULL COMMENT 'Mandant im DWH.',
	AKTION_ID VARCHAR(10) NOT NULL COMMENT 'Aktion-ID',
	ART_ID NUMBER(38,0) NOT NULL COMMENT 'Artikelnummer im DWH. Wird aus matnr erzeugt.',
	DAT_VON DATE COMMENT 'Aktion gültig von.',
	DAT_BIS DATE COMMENT 'Aktion gültig bis.',
	ANGEBOT_ID NUMBER(38,0) NOT NULL COMMENT 'Offer / Angebot-ID.',
	DAT_BELADUNG DATE NOT NULL COMMENT 'Technisches Beladungsdatum.',
	MENGE_OHNE_BESTAND_GENEHMIGT_FG NUMBER(38,0) COMMENT 'Flag: Wird vom User gesetzt, wenn die Werbebestellmenge (z.B. in der Bestellung ans Verteilzentrum) errechnet ohne Berücksichtigung des aktuellen Bestands weiter verwendet werden soll. Ohne Bestandsberücksichtigung ist z.B. für den Fall, dass ein aktuell hoher Bestand vor der Aktion wegen Mhd-Ablauf verfällt, oder es wegen anderer Aktionen zu erwarten ist, dass der Bestand sich abverkauft, weshalb die unreduzierte Bestellmenge genommen werden kann.\n            Einträge werden durch MSTR gepflegt und in Abinitio weiterverarbeitet. Mit oder ohne Bestandsberücksichtigung schließen sich gegenseitig aus. Es kann also immer nur einer von beiden aktiv sein. Die Variante mit zwei Flags wurde anstatt eines Codes gewählt, da es eine übersichtlichere Ansicht in MSTR ermöglicht, als ein drop-down Menü',
	MENGE_MIT_BESTAND_GENEHMIGT_FG NUMBER(38,0) COMMENT 'Flag: Wird vom User gesetzt, wenn die Werbebestellmenge (z.B. in der Bestellung ans Verteilzentrum) errechnet mit Berücksichtigung des aktuellen Bestands weiter verwendet werden soll. Mit Bestandsberücksichtigung ist z.B. für den Fall, dass es einen aktuell hohen Bestand des Artikels gibt, der vor der Aktion wahrscheinlich nicht signifikant abnimmt, was eine Reduktion der Bestellmenge zur Folge haben kann.\n            Einträge werden durch MSTR gepflegt und in Abinitio weiterverarbeitet.  Mit oder ohne Bestandsberücksichtigung schließen sich gegenseitig aus. Es kann also immer nur einer von beiden aktiv sein. Die Variante mit zwei Flags wurde anstatt eines Codes gewählt, da es eine übersichtlichere Ansicht in MSTR ermöglicht, als ein drop-down Menü',
	WERBEAENDERUNG_MENGE_UEBERTRAGEN NUMBER(38,3) COMMENT 'Übertragene Menge zu SAP. (Wird aktuell nicht benutzt. Muss später geklärt werden ob die Spalte bennötigt wird, nachdem weitere Länder (vielleicht alle) an WBS angebunden sind.)',
	TD_UPDATE TIMESTAMP_LTZ(9) COMMENT 'Technical fields for synchronisation framework. Will be delted after last product migration',
	TD_INSERT TIMESTAMP_LTZ(9) COMMENT 'Technical fields for synchronisation framework. Will be delted after last product migration',
	FIXMENGE_WFL_BME NUMBER(38,0) COMMENT 'Die feste Menge, die vom Benutzer eingegeben und auf alle Filialen aufgeteilt werden muss (diese Berechnung wird im Replenishment Core durchgeführt).\n            (FixMenge Bedueted : Freez Diese Menge, um sie an alle Filialen zu aufzuteilen)',
	MENGE_MINDESTPLATZIERUNG_CLUSTER_1_AME NUMBER(38,0) COMMENT 'Minimum Quantity eines Artikels für eine Filiale in Cluster 1. Die Filialen werden je nach Größe in verschiedene Cluster unterteilt, Die Mindestmenge ist im Replenishment Core vorberechnet und wird vom User festgelegt.',
	MENGE_MINDESTPLATZIERUNG_CLUSTER_2_AME NUMBER(38,0) COMMENT 'Minimum Quantity eines Artikels für eine Filiale in Cluster 2. Die Filialen werden je nach Größe in verschiedene Cluster unterteilt, Die Mindestmenge ist im Replenishment Core vorberechnet und wird vom User festgelegt.',
	MENGE_MINDESTPLATZIERUNG_CLUSTER_3_AME NUMBER(38,0) COMMENT 'Minimum Quantity eines Artikels für eine Filiale in Cluster 3. Die Filialen werden je nach Größe in verschiedene Cluster unterteilt, Die Mindestmenge ist im Replenishment Core vorberechnet und wird vom User festgelegt.',
	WFL_MENGE_GEPRUEFT_FG NUMBER(38,0) COMMENT 'Flag,  Waren Fluss (Supply Change Managment Flag), die der Benutzer  auf 1 setzen kann ,um zu markieren, dass er die Mengen fuer diesen Artkel bereits überprüft hat und beibehalten wird,solange es keine Aenderungen bei der Promotion gibt.',
	WFL_NUTZER_KOMMENTAR_TXT VARCHAR(100) COMMENT 'Frei-Text-Feld fuer den Benutzer\n            Dieses Feld dient dazu, einen zusätzlichen Kommentar zu einem Artikel hinzuzufügen. Es dient dazu, besser nachzuvollziehen, was das Problem vorher war.',
	INIT_LIEF_CLEAR_STOCK_ID NUMBER(38,0) COMMENT 'Clear-Stock ID that says how to distribute stock. The goal is to change the clear-stock-flag-logic, so that the user has the possibility to use a third option for distributing the DC stock:\n            0 = do not apply the logic (distribute according to demand in the stores)\n            1 = distribute the whole blocked stock in DC\n            2 = distribute the whole stock in DC (blocked stock + free stock)',
	ESTIMATION_ID NUMBER(38,0) COMMENT 'With this ID the user can decide in which way the estimation for WBS TP2 should be calculated.\n            ID 0 = no estimation\n            ID 1 = calculate normal estimation process\n            ID 2 = only fill up maximum capacity (Berechnung für die Werbung in WBS, aber nur um das Regal aufzufüllen)',
	ADJUSTMENT_ID NUMBER(38,0) COMMENT 'Mit der Adjustment_ID kann der Benutzer entscheiden, auf welche Weise die Nachversorgung in WBS TP1 berechnet werden soll.\n            0 = UDF&R: UDF berechnet die Prognosen und übergibt sie an F&R\n            1 = Standard adjustment (WBS): WBS berechnet die Nachversorgungsmenge und stellt sie den Benutzern als PREX-Upload zur Verfügung.\n            2 = Platzhalter (Stand 28.03.2025)\n            3 = External adjustment: Die SAP Autodispo errechnet keine Mengen. In diesem Fall ist eine manuelle Bestellanlage durch das Land notwendig.',
	GK_FG NUMBER(38,0) COMMENT 'Flag: Gondelkopf',
	constraint PK_TS_MENGENAENDERUNGEN_WRITEBACK primary key (MANDANT_ID, AKTION_ID, ANGEBOT_ID, DAT_BELADUNG, ART_ID)
)COMMENT='SCM-WBS - Writeback of promotional item quantity approval.\n             (Tabelle liegt aktuell im falschen Schema. Sollte in DBP_MSI_DATA sein.)'
;
